//     -Rc2Zip <frozen RC2 ZIP> -Rc3FrozenZip <frozen RC3 ZIP> `
//     -Repo <candidate repo> -OutDir <RELEASE_ASSETS_CANDIDATE>
//
// Exit code 2 = refused by design (documented, not a crash).

console.error('REFUSED: tools/build_release_manifest.mjs is a fail-closed guard in the unified RC3 tree.');
console.error('');
console.error('The external release identity (RELEASE_MANIFEST.json + archive sidecar + release');
console.error('SHA256SUMS.txt) is generated ONLY by tools/build_unified_release.ps1 into');
console.error('RELEASE_ASSETS_CANDIDATE, deterministically and outside the archive.');
console.error('');
console.error('Reproduction command:');
console.error('  powershell -NoProfile -ExecutionPolicy Bypass -File tools/build_unified_release.ps1 \\');
console.error('    -Rc2Zip <frozen RC2 ZIP> -Rc3FrozenZip <frozen RC3 ZIP> \\');
console.error('    -Repo <candidate repo> -OutDir <RELEASE_ASSETS_CANDIDATE>');
